parameters.jsCode:
const items = $input.all();
const results = [];

let vtData = {};
try {
  vtData = $('PhishGuard — VT URL Report').first().json.data || {};
} catch (e) {
  vtData = {};
}
const stats = vtData.attributes?.stats || {};

let urlAnalyzerOutput = '';
try {
  urlAnalyzerOutput = $('PhishGuard — URL Analyzer').first().json.stdout || '';
} catch (e) {
  urlAnalyzerOutput = '';
}

let dnstwistOutput = '';
try {
  dnstwistOutput = $('PhishGuard — dnstwist').first().json.stdout || '';
} catch (e) {
  dnstwistOutput = 'dnstwist data not available';
}

const redirectMatch = urlAnalyzerOutput.match(/Redirects:\s*(\d+)/);
const finalUrlMatch = urlAnalyzerOutput.match(/Final URL:\s*(.+?)\\n/);
const httpCodeMatch = urlAnalyzerOutput.match(/HTTP Code:\s*(\d+)/);

let urlScore = 0;
const malicious = stats.malicious || 0;
const suspicious = stats.suspicious || 0;

if (malicious >= 5) urlScore += 25;
else if (malicious >= 3) urlScore += 20;
else if (malicious >= 1) urlScore += 15;

if (suspicious >= 3) urlScore += 5;
else if (suspicious >= 1) urlScore += 3;

const redirects = redirectMatch ? parseInt(redirectMatch[1]) : 0;
if (redirects >= 3) urlScore += 5;
else if (redirects >= 1) urlScore += 2;

const urlRisks = [];
if (malicious > 0) urlRisks.push(`${malicious} engines flagged URL as malicious`);
if (suspicious > 0) urlRisks.push(`${suspicious} engines flagged URL as suspicious`);
if (redirects >= 3) urlRisks.push(`URL has ${redirects} redirects (evasion technique)`);

const dnstwistResults = {
  scanned: false,
  typosquatDomains: [],
  registeredCount: 0
};

if (!dnstwistOutput.includes('not available') && !dnstwistOutput.includes('NO_URLS')) {
  dnstwistResults.scanned = true;
  const lines = dnstwistOutput.split('\n').filter(l => l.trim().length > 0);
  for (const line of lines) {
    const parts = line.split(',');
    if (parts.length >= 2 && parts[0] !== 'fuzzer') {
      const fuzzer = parts[0] || '';
      const domain = parts[1] || '';
      const dnsA = parts[2] || '';
      if (domain && domain !== '*original*' && dnsA) {
        dnstwistResults.typosquatDomains.push({ type: fuzzer, domain: domain, ip: dnsA });
        dnstwistResults.registeredCount++;
      }
    }
  }
  if (dnstwistResults.registeredCount > 10) {
    urlRisks.push(`${dnstwistResults.registeredCount} typosquat domains found with DNS records — high phishing risk`);
    urlScore += 5;
  } else if (dnstwistResults.registeredCount > 3) {
    urlRisks.push(`${dnstwistResults.registeredCount} typosquat domains found`);
    urlScore += 3;
  }
}

const parsedData = $('PhishGuard — Email Parser').first().json.parsed;
const suspiciousUrls = parsedData.urls.suspicious || [];
if (suspiciousUrls.length > 0) {
  urlScore += 5;
  urlRisks.push(`${suspiciousUrls.length} URLs match suspicious patterns`);
}

urlScore = Math.min(urlScore, 25);

results.push({
  json: {
    urlAnalysis: {
      virusTotal: {
        malicious: malicious,
        suspicious: suspicious,
        harmless: stats.harmless || 0,
        undetected: stats.undetected || 0,
        analysisId: vtData.id || '',
        analysisDate: vtData.attributes?.date || null
      },
      redirects: {
        count: redirects,
        finalUrl: finalUrlMatch ? finalUrlMatch[1] : 'unknown',
        httpCode: httpCodeMatch ? parseInt(httpCodeMatch[1]) : 0
      },
      dnstwist: dnstwistResults,
      suspiciousPatterns: suspiciousUrls,
      risks: urlRisks,
      urlScore: urlScore
    },
    emailId: $('PhishGuard — Email Parser').first().json.emailId,
    parsed: parsedData,
    phishguard: $('PhishGuard — Email Parser').first().json.phishguard
  }
});

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const parsed = item.json.parsed;
  const attachments = parsed.attachments.list || [];

  if (attachments.length === 0) {
    results.push({
      json: {
        attachmentAnalysis: {
          hasAttachments: false,
          totalFiles: 0,
          scannedFiles: [],
          risks: [],
          attachmentScore: 0,
          summary: 'No attachments found in email'
        },
        emailId: item.json.emailId,
        parsed: parsed,
        phishguard: item.json.phishguard
      }
    });
    continue;
  }

  const scannedFiles = [];
  const risks = [];
  let attachmentScore = 0;

  for (const att of attachments) {
    const fileInfo = {
      filename: att.filename,
      extension: att.extension,
      mimeType: att.mimeType,
      size: att.size,
      isDangerous: att.isDangerous,
      riskFactors: []
    };
    if (att.isDangerous) {
      fileInfo.riskFactors.push(`Dangerous file extension: .${att.extension}`);
      attachmentScore += 15;
    }
    if (att.filename.split('.').length > 2) {
      fileInfo.riskFactors.push('Double extension detected (possible disguise)');
      attachmentScore += 10;
    }
    if (fileInfo.riskFactors.length > 0) {
      risks.push(...fileInfo.riskFactors);
    }
    scannedFiles.push(fileInfo);
  }
  attachmentScore = Math.min(attachmentScore, 25);

  results.push({
    json: {
      attachmentAnalysis: {
        hasAttachments: true,
        totalFiles: attachments.length,
        scannedFiles: scannedFiles,
        hasDangerous: attachments.some(a => a.isDangerous),
        risks: risks,
        attachmentScore: attachmentScore,
        summary: `${attachments.length} attachment(s) found`
      },
      emailId: item.json.emailId,
      parsed: parsed,
      phishguard: item.json.phishguard
    },
    binary: item.binary
  });
}
return results;

const items = $input.all();
const results = [];
const headerAnalyzerOutput = $('PhishGuard — Header Analyzer').first().json.stdout || '';
let theHarvesterOutput = '';
try {
  theHarvesterOutput = $('PhishGuard — theHarvester').first().json.stdout || '';
} catch (e) {
  theHarvesterOutput = '';
}

const whoisSection = headerAnalyzerOutput.split('=== DIG ===')[0] || '';
const whoisData = {};
const whoisFields = ['Domain Name', 'Registrar', 'Creation Date', 'Registry Expiry Date'];
for (const field of whoisFields) {
  const match = whoisSection.match(new RegExp(`${field}:\s*(.+?)\\n`, 'i'));
  if (match) whoisData[field] = match[1].trim();
}

let domainAgeDays = null;
if (whoisData['Creation Date']) {
  const created = new Date(whoisData['Creation Date']);
  if (!isNaN(created)) {
    domainAgeDays = Math.floor((Date.now() - created) / (1000 * 60 * 60 * 24));
  }
}

const spfSection = headerAnalyzerOutput.split('=== SPF CHECK ===')[1]?.split('=== DMARC')[0] || '';
const hasSPF = spfSection.toLowerCase().includes('v=spf1');
const dmarcSection = headerAnalyzerOutput.split('=== DMARC CHECK ===')[1] || '';
const hasDMARC = dmarcSection.toLowerCase().includes('v=dmarc');

let headerScore = 0;
const headerRisks = [];
if (domainAgeDays !== null && domainAgeDays < 30) { headerScore += 15; headerRisks.push('Domain registered < 30 days ago'); }
if (!hasSPF) { headerScore += 5; headerRisks.push('No SPF record found'); }
if (!hasDMARC) { headerScore += 5; headerRisks.push('No DMARC record found'); }

results.push({
  json: {
    headerAnalysis: {
      whois: whoisData,
      domainAgeDays: domainAgeDays,
      spf: { found: hasSPF, record: spfSection.trim() },
      dmarc: { found: hasDMARC, record: dmarcSection.trim() },
      risks: headerRisks,
      headerScore: headerScore
    },
    emailId: $('PhishGuard — Email Parser').first().json.emailId,
    parsed: $('PhishGuard — Email Parser').first().json.parsed,
    phishguard: $('PhishGuard — Email Parser').first().json.phishguard
  }
});
return results;

let headerData = {};
try { headerData = $('PhishGuard — Header and theHarvester Parser').first().json; } catch (e) { headerData = { headerAnalysis: { headerScore: 0, risks: [] } }; }
let urlData = {};
try { urlData = $('PhishGuard — URL Parser').first().json; } catch (e) { urlData = { urlAnalysis: { urlScore: 0, risks: [] } }; }
let attachmentData = {};
try { attachmentData = $('PhishGuard — Attachment Parser').first().json; } catch (e) { attachmentData = { attachmentAnalysis: { attachmentScore: 0, risks: [] } }; }

const headerScore = headerData.headerAnalysis?.headerScore || 0;
const urlScore = urlData.urlScore || urlData.urlAnalysis?.urlScore || 0;
const attachmentScore = attachmentData.attachmentAnalysis?.attachmentScore || 0;
const keywordCount = headerData.phishguard?.keywordCount || 0;

let keywordScore = 0;
if (keywordCount >= 5) keywordScore = 25;
else if (keywordCount >= 3) keywordScore = 15;
else if (keywordCount >= 2) keywordScore = 10;
else if (keywordCount >= 1) keywordScore = 5;

const totalScore = Math.min(keywordScore + headerScore + urlScore + attachmentScore, 100);
let threatLevel = 'LOW';
if (totalScore >= 70) threatLevel = 'CRITICAL';
else if (totalScore >= 50) threatLevel = 'HIGH';
else if (totalScore >= 30) threatLevel = 'MEDIUM';

const allRisks = [
  ...(headerData.headerAnalysis?.risks || []),
  ...(urlData.urlAnalysis?.risks || []),
  ...(attachmentData.attachmentAnalysis?.risks || [])
];

return [{
  json: {
    threatAssessment: {
      totalScore: totalScore,
      threatLevel: threatLevel,
      breakdown: { keywordScore, headerScore, urlScore, attachmentScore },
      allRisks: allRisks
    },
    emailSummary: {
      from: headerData.parsed?.headers?.from || '',
      fromEmail: headerData.parsed?.headers?.fromEmail || '',
      senderDomain: headerData.parsed?.headers?.senderDomain || '',
      subject: headerData.parsed?.headers?.subject || '',
      to: headerData.parsed?.headers?.to || '',
      date: headerData.parsed?.headers?.date || '',
      urlCount: headerData.parsed?.urls?.count || 0,
      attachmentCount: headerData.parsed?.attachments?.count || 0
    },
    timestamp: new Date().toISOString()
  }
}];

