parameters.jsCode:
const items = $input.all();
const aiOutput = items[0]?.json?.output || '';
let mergeData = {};
try { mergeData = $('PhishGuard — Merge Results').first().json; } catch (e) { mergeData = {}; }

const parseField = (text, field) => {
  const match = text.match(new RegExp(`${field}:\s*([\s\S]*?)(?=\n[A-Z_]+:|$)`, 'i'));
  return match ? match[1].trim() : 'N/A';
};

const verdict = parseField(aiOutput, 'VERDICT');
const confidence = parseField(aiOutput, 'CONFIDENCE');
let finalScore = mergeData.threatAssessment?.totalScore || 30;
let finalThreatLevel = mergeData.threatAssessment?.threatLevel || 'MEDIUM';

if (verdict.includes('PHISHING') && confidence.includes('HIGH')) {
  finalScore = Math.max(finalScore, 75);
  finalThreatLevel = 'CRITICAL';
}

return [{
  json: {
    finalVerdict: { aiVerdict: verdict, aiConfidence: confidence, finalScore, finalThreatLevel },
    aiAnalysis: { 
      socialEngineering: parseField(aiOutput, 'SOCIAL_ENGINEERING_TACTICS'),
      technicalIndicators: parseField(aiOutput, 'TECHNICAL_INDICATORS'),
      recommendation: parseField(aiOutput, 'RECOMMENDATION'),
      executiveSummary: parseField(aiOutput, 'EXECUTIVE_SUMMARY')
    },
    emailSummary: mergeData.emailSummary,
    threatAssessment: mergeData.threatAssessment,
    timestamp: mergeData.timestamp
  }
}];
